import{_ as h,o as t,c as i,a3 as o}from"./chunks/framework.DX_KL3e0.js";const u=JSON.parse('{"title":"Hiệu Suất Phòng Họp","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/hieu-suat-phong-hop.md","filePath":"chuc-nang/hieu-suat-phong-hop.md","lastUpdated":1782639524000}'),a={name:"chuc-nang/hieu-suat-phong-hop.md"};function g(l,n,c,e,r,p){return t(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="hieu-suat-phong-hop" tabindex="-1">Hiệu Suất Phòng Họp <a class="header-anchor" href="#hieu-suat-phong-hop" aria-label="Permalink to &quot;Hiệu Suất Phòng Họp&quot;">​</a></h1><p>Trang <strong>Hiệu Suất Phòng Họp</strong> giúp theo dõi mức độ sử dụng phòng họp theo thời gian, khung giờ cao điểm và tỷ lệ nhận phòng thực tế.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/room-bookings/thong-ke</code>.</li><li><strong>Ai dùng được:</strong> người có quyền xem thống kê đặt phòng.</li><li><strong>Dùng để:</strong> đánh giá mức độ sử dụng phòng, no-show và hiệu suất theo từng phòng.</li></ul></div><h2 id="cac-chi-so-chinh" tabindex="-1">Các chỉ số chính <a class="header-anchor" href="#cac-chi-so-chinh" aria-label="Permalink to &quot;Các chỉ số chính&quot;">​</a></h2><p>Trang thống kê thường hiển thị:</p><ul><li><strong>Tổng booking</strong></li><li><strong>Tỷ lệ nhận phòng</strong></li><li><strong>Số no-show</strong></li><li><strong>Tổng giờ đặt</strong></li><li><strong>Số phòng có sử dụng</strong></li></ul><p>Ngoài ra còn có:</p><ul><li>biểu đồ <strong>giờ cao điểm</strong></li><li>bảng <strong>theo phòng</strong></li><li>bộ lọc theo mốc <strong>7 / 30 / 90 ngày</strong></li></ul><h2 id="cach-đoc-du-lieu" tabindex="-1">Cách đọc dữ liệu <a class="header-anchor" href="#cach-đoc-du-lieu" aria-label="Permalink to &quot;Cách đọc dữ liệu&quot;">​</a></h2><h3 id="gio-cao-điem" tabindex="-1">Giờ cao điểm <a class="header-anchor" href="#gio-cao-điem" aria-label="Permalink to &quot;Giờ cao điểm&quot;">​</a></h3><p>Biểu đồ giờ cao điểm cho biết khung giờ nào bắt đầu cuộc họp nhiều nhất. Dữ liệu này hữu ích khi:</p><ul><li>sắp lịch họp nội bộ</li><li>cân nhắc mở thêm phòng</li><li>điều chỉnh quy tắc vận hành phòng</li></ul><h3 id="theo-phong" tabindex="-1">Theo phòng <a class="header-anchor" href="#theo-phong" aria-label="Permalink to &quot;Theo phòng&quot;">​</a></h3><p>Bảng theo phòng cho biết:</p><ul><li>mỗi phòng được đặt bao nhiêu buổi</li><li>tổng số giờ sử dụng</li><li>số lượt nhận phòng thực tế</li><li>tỷ lệ nhận phòng</li></ul><p>Nếu một phòng có tỷ lệ nhận phòng thấp hoặc no-show cao, nên kiểm tra lại thói quen đặt phòng hoặc quy trình xác nhận sử dụng.</p><h2 id="khi-nao-nen-xem-trang-nay" tabindex="-1">Khi nào nên xem trang này <a class="header-anchor" href="#khi-nao-nen-xem-trang-nay" aria-label="Permalink to &quot;Khi nào nên xem trang này&quot;">​</a></h2><p>Phù hợp cho:</p><ul><li>Admin vận hành văn phòng</li><li>bộ phận hành chính</li><li>người phụ trách tối ưu tài nguyên phòng họp</li></ul><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>No-show là gì?</strong><br> Là các lượt đã đặt nhưng thực tế không sử dụng hoặc không xác nhận nhận phòng.</p><p><strong>Vì sao tỷ lệ nhận phòng của một phòng thấp?</strong><br> Thường do người dùng đặt trước rồi không dùng, hoặc lịch họp thay đổi nhưng không hủy trên hệ thống.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/dat-phong.html">Đặt Phòng Họp</a></p>',24)])])}const d=h(a,[["render",g]]);export{u as __pageData,d as default};
